<script setup>
import { onMounted, ref } from 'vue';
import AppLayout from '../../components/layout/AppLayout.vue';
import ProcurementPurchasesPanel from '../../components/common/ProcurementPurchasesPanel.vue';
import { purchaseWorkflow } from '../../services/purchaseWorkflow';
import { orderError } from '../../services/orderWorkflow';
import { useRouter } from '../../navigation';
const router = useRouter(), requests = ref([]), error = ref(''), loading = ref(true);
onMounted(async () => { try { requests.value = (await purchaseWorkflow.requests()).filter(record => record.status === 'MENUNGGU_FINANCE'); } catch (cause) { error.value = orderError(cause); } finally { loading.value = false; } });
</script>
<template><AppLayout><template #header><div class="flex flex-wrap justify-between gap-3"><div><h1 class="text-2xl font-semibold text-slate-900">Transaksi Pembelian</h1><p class="mt-1 text-sm text-slate-600">Pengadaan dan tindak lanjut supplier berdasarkan pengajuan Gudang.</p></div><button type="button" class="rounded-lg bg-sky-700 px-4 py-2 text-sm font-semibold text-white" @click="router.push('/finance/purchases/create')">Proses Pengajuan Gudang</button></div></template><div class="space-y-6"><p v-if="error" role="alert" class="rounded-lg bg-red-50 p-4 text-red-800">{{ error }}</p><section class="space-y-3 rounded-xl border bg-white p-5"><h2 class="text-lg font-semibold">Pengajuan Gudang Menunggu Pembelian</h2><p v-if="loading" role="status">Memuat pengajuan…</p><p v-else-if="!requests.length" class="text-sm text-slate-600">Belum ada pengajuan baru yang menunggu Finance.</p><article v-for="record in requests" :key="record.id" class="rounded-lg border p-4 text-sm"><h3 class="font-semibold">{{ record.request_code }}</h3><p class="mt-1 text-slate-600">{{ record.order_number || 'Belum terhubung ke pesanan' }} · {{ record.project_name }}</p><p v-if="record.requirements_changed" class="mt-2 text-amber-800">Kebutuhan berubah atau referensi pesanan belum tersedia. Warehouse perlu membatalkan pengajuan dan membuat ulang.</p><button v-else type="button" class="mt-3 rounded-lg border px-3 py-2 font-semibold" @click="router.push({ path: '/finance/purchases/create', query: { requestCode: record.request_code } })">Pilih Supplier &amp; Beli {{ record.request_code }}</button></article></section><ProcurementPurchasesPanel mode="finance" /></div></AppLayout></template>
